export const REGION_NAMES: Record<string, string> = {
  'north-america': 'North America',
  europe: 'Europe',
};

const NORTH_AMERICA = ['US', 'CA', 'MX'];
const EUROPE = ['GB', 'IE', 'FR', 'DE', 'ES', 'PT', 'IT', 'NL', 'BE', 'LU', 'CH', 'AT', 'DK', 'SE', 'NO', 'FI', 'IS',
  'PL', 'CZ', 'SK', 'HU', 'SI', 'HR', 'RO', 'BG', 'GR', 'EE', 'LV', 'LT', 'UA'];

function regionForCountry(country: string | null | undefined): string | undefined {
  if (!country) return undefined;
  const c = country.toUpperCase();
  if (NORTH_AMERICA.includes(c)) return 'north-america';
  if (EUROPE.includes(c)) return 'europe';
  return undefined;
}

/** Region from the device's language/region setting. No location permission involved. */
export function detectRegion(): string | undefined {
  try {
    for (const locale of getLocales()) {
      const region = regionForCountry(locale.regionCode);
      if (region) return region;
    }
  } catch {}
  try {
    const locale = Intl.DateTimeFormat().resolvedOptions().locale;
    return regionForCountry(locale.split(/[-_]/).find((p) => /^[A-Za-z]{2}$/.test(p) && p === p.toUpperCase()));
  } catch {}
  return undefined;
}

export function birdsFor(region: string | undefined, worldwide: boolean): LibraryBird[] {
  if (worldwide || !region) return BIRDS;
  const local = BIRDS.filter((b) => b.regions.includes(region));
  return local.length ? local : BIRDS;
}

export const birdById = (id: string | undefined) => BIRDS.find((b) => b.id === id);
